"""
Constants for the Agents service.

Centralizes AI tool definitions, timing intervals, TTLs, and file paths
used by discovery, registry, transcripts, and hooks.
"""

import os
from dataclasses import dataclass


@dataclass(frozen=True)
class AIToolConfig:
    """Configuration for a known AI coding tool."""

    tool_id: str
    display_name: str
    process_names: tuple[str, ...] = ()


# ---------------------------------------------------------------------------
# Known AI tool definitions
# ---------------------------------------------------------------------------

AI_TOOLS: dict[str, AIToolConfig] = {
    "claude": AIToolConfig(
        tool_id="claude",
        display_name="Claude Code",
        process_names=("claude",),
    ),
    "codeq": AIToolConfig(
        tool_id="codeq",
        display_name="codeq",
        process_names=("codeq", "codeq-bin", "opencode", ".opencode"),
    ),
    "codex": AIToolConfig(
        tool_id="codex",
        display_name="Codex",
        process_names=("codex",),
    ),
}

# Reverse lookup: process name -> tool_id
PROCESS_NAME_TO_TOOL: dict[str, str] = {}
for _tool_id, _cfg in AI_TOOLS.items():
    for _pname in _cfg.process_names:
        PROCESS_NAME_TO_TOOL[_pname] = _tool_id

